void initialize_example_module(ModuleInitializationLevel p_level) {
        if (p_level != MODULE_INITIALIZATION_LEVEL_SCENE) {
                return;
        }

        GDREGISTER_CLASS(ExampleRef);
        GDREGISTER_CLASS(ExampleMin);
        GDREGISTER_CLASS(Example);
        GDREGISTER_VIRTUAL_CLASS(ExampleVirtual);
        GDREGISTER_ABSTRACT_CLASS(ExampleAbstractBase);
        GDREGISTER_CLASS(ExampleConcrete);
        GDREGISTER_CLASS(ExampleBase);
        GDREGISTER_CLASS(ExampleChild);
        GDREGISTER_RUNTIME_CLASS(ExampleRuntime);
}

void uninitialize_example_module(ModuleInitializationLevel p_level) {
        if (p_level != MODULE_INITIALIZATION_LEVEL_SCENE) {
                return;
        }
}

extern "C" {
// Initialization.
GDExtensionBool GDE_EXPORT example_library_init(GDExtensionInterfaceGetProcAddress p_get_proc_address, GDExtensionClassLibraryPtr p_library, GDExtensionInitiali
zation *r_initialization) {
        godot::GDExtensionBinding::InitObject init_obj(p_get_proc_address, p_library, r_initialization);

        init_obj.register_initializer(initialize_example_module);
        init_obj.register_terminator(uninitialize_example_module);
        init_obj.set_minimum_library_initialization_level(MODULE_INITIALIZATION_LEVEL_SCENE);

        return init_obj.init();
}
